import threading
import time
import hashlib
import os
import re
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

# Thread-safe session store
class SessionStore:
    def __init__(self):
        self._sessions = {}
        self._lock = threading.Lock()

    def create_session(self, user_id, role):
        token = hashlib.sha256(os.urandom(32)).hexdigest()
        with self._lock:
            self._sessions[token] = {
                'user_id': user_id,
                'role': role,
                'created_at': time.time()
            }
        return token

    def get_session(self, token):
        with self._lock:
            return self._sessions.get(token, None)

    def update_role(self, token, new_role):
        with self._lock:
            if token in self._sessions:
                self._sessions[token]['role'] = new_role
                return True
        return False

    def invalidate_session(self, token):
        with self._lock:
            if token in self._sessions:
                del self._sessions[token]
                return True
        return False

sessions = SessionStore()

# Permission cache to reduce lock contention
class PermissionCache:
    def __init__(self, ttl=2.0):
        self._cache = {}
        self._ttl = ttl

    def get_permission(self, token):
        entry = self._cache.get(token)
        if entry and (time.time() - entry['timestamp']) < self._ttl:
            return entry['role']
        return None

    def set_permission(self, token, role):
        self._cache[token] = {
            'role': role,
            'timestamp': time.time()
        }

    def invalidate(self, token):
        # Bug: only removes from cache, doesn't prevent re-caching
        # from a concurrent request that already read the session
        if token in self._cache:
            del self._cache[token]

perm_cache = PermissionCache(ttl=2.0)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        if not token:
            return jsonify({'error': 'No session token'}), 401

        # First check permission cache (no lock needed)
        cached_role = perm_cache.get_permission(token)
        if cached_role is not None:
            g.role = cached_role
            g.token = token
            return f(*args, **kwargs)

        # Cache miss: check session store
        session = sessions.get_session(token)
        if session is None:
            return jsonify({'error': 'Invalid session'}), 401

        # Cache the permission for future requests
        perm_cache.set_permission(token, session['role'])
        g.role = session['role']
        g.token = token
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    @require_auth
    def decorated(*args, **kwargs):
        if g.role != 'admin':
            return jsonify({'error': 'Admin required'}), 403
        return f(*args, **kwargs)
    return decorated

# URL validation for webhook feature (red herring - safe in both)
def validate_webhook_url(url):
    """Validate webhook URLs to prevent SSRF"""
    if not url:
        return False
    pattern = r'^https://[a-zA-Z0-9][a-zA-Z0-9\-\.]+\.[a-zA-Z]{2,}/[a-zA-Z0-9/\-_]+$'
    if not re.match(pattern, url):
        return False
    # Block internal networks
    blocked = ['localhost', '127.0.0.1', '10.', '172.16.', '192.168.', '169.254.']
    for b in blocked:
        if b in url.lower():
            return False
    return True

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username', '')
    password = data.get('password', '')

    # Simplified auth (demo)
    if username == 'admin' and password == 'admin_pass_demo':
        token = sessions.create_session(username, 'admin')
        return jsonify({'token': token})
    elif username and password:
        token = sessions.create_session(username, 'user')
        return jsonify({'token': token})
    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/demote', methods=['POST'])
@require_admin
def demote_user():
    """Admin demotes a user (or themselves) to regular user"""
    data = request.get_json()
    target_token = data.get('target_token')
    if not target_token:
        return jsonify({'error': 'No target specified'}), 400

    # Update role in session store
    sessions.update_role(target_token, 'user')
    # Invalidate their permission cache so they get fresh role
    perm_cache.invalidate(target_token)

    return jsonify({'status': 'demoted'})

@app.route('/revoke', methods=['POST'])
@require_admin
def revoke_session():
    """Admin revokes a session entirely"""
    data = request.get_json()
    target_token = data.get('target_token')
    if not target_token:
        return jsonify({'error': 'No target specified'}), 400

    # Invalidate cache first, then destroy session
    perm_cache.invalidate(target_token)
    sessions.invalidate_session(target_token)

    return jsonify({'status': 'revoked'})

@app.route('/admin/secrets', methods=['GET'])
@require_admin
def get_secrets():
    return jsonify({'secrets': ['secret_key_1', 'secret_key_2', 'database_password']})

@app.route('/admin/webhook', methods=['POST'])
@require_admin
def set_webhook():
    data = request.get_json()
    url = data.get('url', '')
    if not validate_webhook_url(url):
        return jsonify({'error': 'Invalid webhook URL'}), 400
    return jsonify({'status': 'webhook set', 'url': url})

@app.route('/profile', methods=['GET'])
@require_auth
def get_profile():
